 gate=all(v(p)>v(c) for c in controls);compat={'native_original_CE':v('native_original_CE'),'prepared_A_CE':v('softtoken_A'),'prepared_fused_CE':v('softtoken_fusedABC'),'transport_prepared_A_CE':v('transport_CE_A'),'transport_fused_CE':v('transport_CE_fusedABC'),'not_a_source_space_fault_proof':True};decision={'primary':p,'mIoU_percent':v(p),'gains_pp':{c:v(p)-v(c) for c in controls},'passes_development_gates':gate,'robust_adoption':False,'decision':'lock_before_expansion_required' if gate else 'do_not_adopt_paired_BN_transport_recipe','n':768,'running_statistics_only_TTA':True,'learned_weights_updated':False,'gradient_or_pseudo_labels':False,'primary_not_switched':True,'FINAL_access':False}
